/** Form definitions generated by wp2emdash scaffold from the WordPress form plugin (src/forms/*.json). */
export interface FormField {
	name: string;
	label: string;
	type: "text" | "email" | "tel" | "number" | "url" | "date" | "textarea" | "select" | "checkbox";
	required?: boolean;
	placeholder?: string;
	options?: string[];
	half?: boolean;
	autocomplete?: string;
}
export interface FormDefinition {
	id: string;
	title: string;
	submitLabel: string;
	successMessage: string;
	fields: FormField[];
	/** true when the site handles sensitive data: only the fields the owner approved are in `fields`, nothing is stored. */
	sensitive?: boolean;
	/** Shown above the submit button (e.g. "Please don't include health details here"). */
	notice?: string;
	/** After a successful send: hide the form and show the message, or reset it (default). */
	afterSubmit?: "hide" | "reset";
}

const files = import.meta.glob<{ default: FormDefinition }>("./*.json", { eager: true });
const forms = new Map(Object.values(files).map((m) => [m.default.id, m.default]));

export function getForm(id: string | undefined | null): FormDefinition | undefined {
	return id ? forms.get(String(id)) : undefined;
}
